const n = parseInt(readline());
const VOWELS = new Set(['A','E','I','O','U']);
const labels = ['INERT','PASSIVE','MONITOR','ACTIVE','APEX'];

for (let i = 0; i < n; i++) {
    const obj = readline();
    const count = new Set([...obj].filter(c => VOWELS.has(c))).size;

    console.log(labels[Math.min(count, 4)]);
}
